import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#game');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0x102329); scene.fog=new THREE.FogExp2(0x102329,.033);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,100);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15;
scene.add(new THREE.HemisphereLight(0xb8ddd2,0x26312d,2.1));
const moon=new THREE.DirectionalLight(0xd4e7df,2.8); moon.position.set(-5,12,7); moon.castShadow=true; moon.shadow.mapSize.set(1024,1024); moon.shadow.camera.left=-18;moon.shadow.camera.right=18;moon.shadow.camera.top=18;moon.shadow.camera.bottom=-18;scene.add(moon);
const goldLight=new THREE.PointLight(0xe4ad5e,18,16,2);goldLight.position.set(0,3,-4);scene.add(goldLight);
const cyanLight=new THREE.PointLight(0x5bcfc3,14,13,2);cyanLight.position.set(-7,2,2);scene.add(cyanLight);
const mat=(color,roughness=.72,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const mats={ground:mat(0x263c38),stone:mat(0x4b5c53),dark:mat(0x172b2e),gold:mat(0xc99c54,.35,.55),teal:mat(0x61d5c7,.28,.25),cloth:mat(0x283c3a),skin:mat(0xb9c2a8),enemy:mat(0x536d58),enemyDark:mat(0x253c32),eye:new THREE.MeshStandardMaterial({color:0xff8557,emissive:0xd43b22,emissiveIntensity:2}),crystal:new THREE.MeshStandardMaterial({color:0x81d8c6,emissive:0x3cafa0,emissiveIntensity:1.6,roughness:.22,metalness:.18})};
const floor=new THREE.Mesh(new THREE.CircleGeometry(14,80),mats.ground);floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;scene.add(floor);
const grid=new THREE.GridHelper(28,28,0x668176,0x425b50);grid.position.y=.015;grid.material.transparent=true;grid.material.opacity=.16;scene.add(grid);
function ring(radius,tube,color,y=0.03){const o=new THREE.Mesh(new THREE.TorusGeometry(radius,tube,8,100),new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:.35,transparent:true,opacity:.6}));o.rotation.x=Math.PI/2;o.position.y=y;scene.add(o);return o}
ring(12.6,.075,0xb38a4c);ring(11.9,.025,0x5b8c79,.04);ring(3.2,.045,0x528e83,.025);
// Broken stones, rune markers, and the glowing altar make a readable arena boundary.
const rand=(a,b)=>a+Math.random()*(b-a);
for(let i=0;i<18;i++){
 const a=i/18*Math.PI*2,r=rand(11,13),x=Math.cos(a)*r,z=Math.sin(a)*r;
 const h=rand(.8,2.6),w=rand(.45,.9);const pillar=new THREE.Mesh(new THREE.CylinderGeometry(w*.72,w,h,5),i%3===0?mats.gold:mats.stone);pillar.position.set(x,h/2,z);pillar.rotation.y=rand(0,2);pillar.rotation.z=rand(-.12,.12);pillar.castShadow=true;pillar.receiveShadow=true;scene.add(pillar);
 const shard=new THREE.Mesh(new THREE.OctahedronGeometry(.13,0),mats.crystal);shard.position.set(x,h+.16,z);scene.add(shard);
}
const altar=new THREE.Group();altar.position.set(0,0,-4.5);scene.add(altar);
const base=new THREE.Mesh(new THREE.CylinderGeometry(1.35,1.6,.38,8),mats.dark);base.position.y=.2;base.castShadow=true;altar.add(base);
const baseRing=new THREE.Mesh(new THREE.TorusGeometry(1.18,.06,8,48),mats.gold);baseRing.rotation.x=Math.PI/2;baseRing.position.y=.43;altar.add(baseRing);
const altarCrystal=new THREE.Mesh(new THREE.OctahedronGeometry(.8,0),mats.crystal);altarCrystal.position.y=1.5;altarCrystal.scale.set(.7,1.25,.7);altarCrystal.castShadow=true;altar.add(altarCrystal);
const altarBeam=new THREE.PointLight(0x67d9c6,7,8,2);altarBeam.position.y=1.5;altar.add(altarBeam);
// Sparse atmospheric embers.
const particles=[];for(let i=0;i<75;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(rand(.015,.045),5,5),i%3?mats.gold:mats.crystal);m.position.set(rand(-13,13),rand(.2,5),rand(-13,13));scene.add(m);particles.push({mesh:m,phase:rand(0,6),speed:rand(.4,1.3),origin:m.position.y})}
function makeHero(){
 const g=new THREE.Group();const body=new THREE.Group();g.add(body);g.userData.body=body;
 const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.38,.62,4,8),mats.cloth);torso.position.y=1.28;torso.castShadow=true;body.add(torso);
 const chest=new THREE.Mesh(new THREE.BoxGeometry(.61,.43,.3),mats.gold);chest.position.set(0,1.43,.17);chest.castShadow=true;body.add(chest);
 const rune=new THREE.Mesh(new THREE.OctahedronGeometry(.105,0),mats.crystal);rune.position.set(0,1.44,.34);body.add(rune);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.28,10,8),mats.skin);head.position.y=2.02;head.castShadow=true;body.add(head);
 const helmet=new THREE.Mesh(new THREE.ConeGeometry(.34,.48,5),mats.gold);helmet.position.y=2.31;helmet.rotation.y=.3;helmet.castShadow=true;body.add(helmet);
 const cape=new THREE.Mesh(new THREE.ConeGeometry(.48,.95,5),mats.dark);cape.position.set(0,.95,-.29);cape.rotation.x=Math.PI;cape.castShadow=true;body.add(cape);
 const armGeo=new THREE.CapsuleGeometry(.12,.48,3,6);for(const s of [-1,1]){const arm=new THREE.Mesh(armGeo,s<0?mats.cloth:mats.skin);arm.position.set(s*.48,1.36,0);arm.rotation.z=s*.2;arm.castShadow=true;body.add(arm)}
 const legGeo=new THREE.CapsuleGeometry(.14,.43,3,6);for(const s of [-1,1]){const leg=new THREE.Mesh(legGeo,mats.dark);leg.position.set(s*.2,.45,0);leg.castShadow=true;body.add(leg)}
 const sword=new THREE.Group();const blade=new THREE.Mesh(new THREE.BoxGeometry(.12,.76,.1),mats.crystal);blade.position.y=.48;blade.castShadow=true;sword.add(blade);const hilt=new THREE.Mesh(new THREE.BoxGeometry(.34,.09,.16),mats.gold);hilt.position.y=.08;sword.add(hilt);const handle=new THREE.Mesh(new THREE.CylinderGeometry(.045,.05,.22,6),mats.dark);handle.position.y=-.07;sword.add(handle);sword.position.set(.56,1.2,.12);sword.rotation.z=-.42;body.add(sword);g.userData.sword=sword;
 const aura=new THREE.Mesh(new THREE.CylinderGeometry(.52,.67,.06,24),new THREE.MeshBasicMaterial({color:0x61d5c7,transparent:true,opacity:.25}));aura.position.y=.055;g.add(aura);
 const shadow=new THREE.Mesh(new THREE.CircleGeometry(.7,24),new THREE.MeshBasicMaterial({color:0x061013,transparent:true,opacity:.34,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.025;g.add(shadow);
 g.position.y=0;g.traverse(o=>{if(o.isMesh)o.frustumCulled=false});scene.add(g);return g
}
const hero=makeHero();hero.position.set(0,0,3.8);
const state={running:false,paused:false,level:1,xp:0,nextXp:24,hp:100,maxHp:100,damage:38,speed:5.1,attackSpeed:.55,range:2.6,armor:0,kills:0,time:0,attackTimer:0,dashTimer:0,invuln:0,spawnTimer:1,walk:0,attackAnim:0,enemies:[],effects:[],keys:{},joy:{x:0,y:0},lastLevel:1};
const enemyMaterials=[mats.enemy,new THREE.MeshStandardMaterial({color:0x765844,roughness:.8}),new THREE.MeshStandardMaterial({color:0x64577c,roughness:.7})];
function makeEnemy(){
 const g=new THREE.Group();const type=Math.floor(Math.random()*3),scale=type===1?1.2:type===2?.82:1;g.scale.setScalar(scale);
 const core=new THREE.Mesh(new THREE.SphereGeometry(.44,9,7),enemyMaterials[type]);core.position.y=.72;core.scale.set(1,1.15,.88);core.castShadow=true;g.add(core);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.31,8,7),enemyMaterials[type]);head.position.set(0,1.28,.16);head.castShadow=true;g.add(head);
 for(const s of [-1,1]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.065,7,6),mats.eye);eye.position.set(s*.14,1.3,.42);g.add(eye);const spike=new THREE.Mesh(new THREE.ConeGeometry(.12,.4,5),mats.enemyDark);spike.position.set(s*.24,1.58,.08);spike.rotation.z=s*-.35;g.add(spike)}
 for(const s of [-1,1]){const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.13,.5,3,5),enemyMaterials[type]);arm.position.set(s*.46,.7,.08);arm.rotation.z=s*.42;arm.castShadow=true;g.add(arm)}
 const shadow=new THREE.Mesh(new THREE.CircleGeometry(.55,16),new THREE.MeshBasicMaterial({color:0x050b0a,transparent:true,opacity:.46,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.025;g.add(shadow);
 const hpBack=new THREE.Mesh(new THREE.PlaneGeometry(.72,.075),new THREE.MeshBasicMaterial({color:0x17201c,side:THREE.DoubleSide,depthTest:false}));hpBack.position.set(0,1.92,0);g.add(hpBack);
 const hpFront=new THREE.Mesh(new THREE.PlaneGeometry(.68,.045),new THREE.MeshBasicMaterial({color:0xd77953,side:THREE.DoubleSide,depthTest:false}));hpFront.position.set(0,1.92,.005);g.add(hpFront);
 const angle=rand(0,Math.PI*2),dist=rand(9.3,11.4);g.position.set(hero.position.x+Math.cos(angle)*dist,0,hero.position.z+Math.sin(angle)*dist);
 const scaleLv=1+(state.level-1)*.025;const max=55+state.level*2.2;
 const e={group:g,hp:max,maxHp:max,speed:rand(.85,1.25)+Math.min(state.level*.004,.42),damage:7+Math.floor(state.level*.12),xp:10+Math.floor(state.level*.26),attack:rand(.5,1.5),scale:scaleLv,hpFront};g.scale.multiplyScalar(scaleLv);scene.add(g);state.enemies.push(e);return e
}
function burst(position,color=0x70d9c5,count=9){for(let i=0;i<count;i++){const mesh=new THREE.Mesh(new THREE.OctahedronGeometry(rand(.045,.11),0),new THREE.MeshBasicMaterial({color,transparent:true}));mesh.position.copy(position);scene.add(mesh);state.effects.push({mesh,life:rand(.28,.65),max:.65,vel:new THREE.Vector3(rand(-2,2),rand(1,4),rand(-2,2))})}}
function floatLabel(text,pos,color='#fff0c9'){const el=document.createElement('div');el.className='feed-item';el.style.position='absolute';el.style.left='50%';el.style.top='43%';el.style.border='0';el.style.background='none';el.style.color=color;el.style.fontWeight='800';el.style.fontSize='14px';el.style.textShadow='0 2px 6px #000';el.textContent=text;document.querySelector('#game-shell').append(el);setTimeout(()=>el.remove(),650)}
function addXp(amount){state.xp+=amount;while(state.xp>=state.nextXp&&state.level<100){state.xp-=state.nextXp;state.level++;state.nextXp=Math.floor(24+state.level*1.42);state.maxHp+=2;state.hp=Math.min(state.maxHp,state.hp+12);state.damage+=1.2;showToast(`NÍVEL ${String(state.level).padStart(2,'0')} — PODER AMPLIADO`);if(state.level%5===0){state.paused=true;openUpgrades();break}}if(state.level>=100)winGame();updateHud()}
function killEnemy(e){scene.remove(e.group);state.enemies=state.enemies.filter(x=>x!==e);state.kills++;addXp(e.xp);burst(e.group.position.clone().add(new THREE.Vector3(0,1,0)),0x91e4c9,13);feedKill(e.xp)}
function feedKill(xp){const feed=document.querySelector('#combat-feed');const item=document.createElement('div');item.className='feed-item';item.innerHTML=`CRIATURA ELIMINADA <em>+${xp} ✦</em>`;feed.prepend(item);while(feed.children.length>3)feed.lastChild.remove();setTimeout(()=>item.remove(),2300)}
function showToast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>t.classList.remove('show'),1500)}
function updateHud(){document.querySelector('#level-number').textContent=String(state.level).padStart(2,'0');document.querySelector('#progress-level').textContent=String(state.level).padStart(2,'0');document.querySelector('#xp-text').textContent=`${Math.floor(state.xp)} / ${state.nextXp}`;document.querySelector('#xp-fill').style.width=`${Math.min(100,state.xp/state.nextXp*100)}%`;document.querySelector('#health-text').textContent=`${Math.ceil(state.hp)} / ${state.maxHp}`;document.querySelector('#health-fill').style.width=`${Math.max(0,state.hp/state.maxHp*100)}%`;document.querySelector('#kill-count').textContent=state.kills}

