function updateHud(){document.querySelector('#level-number').textContent=String(state.level).padStart(2,'0');document.querySelector('#progress-level').textContent=String(state.level).padStart(2,'0');document.querySelector('#xp-text').textContent=`${Math.floor(state.xp)} / ${state.nextXp}`;document.querySelector('#xp-fill').style.width=`${Math.min(100,state.xp/state.nextXp*100)}%`;document.querySelector('#health-text').textContent=`${Math.ceil(state.hp)} / ${state.maxHp}`;document.querySelector('#health-fill').style.width=`${Math.max(0,state.hp/state.maxHp*100)}%`;document.querySelector('#kill-count').textContent=state.kills}
function openUpgrades(){const choices=[{icon:'✦',name:'CORTE RÚNICO',desc:'Ataques causam +35% de dano.',apply:()=>state.damage*=1.35},{icon:'⌁',name:'PASSO DO VENTO',desc:'Movimento +18% e esquiva recarrega rápido.',apply:()=>state.speed*=1.18},{icon:'♥',name:'CORAÇÃO DE PEDRA',desc:'Vitalidade máxima +30 e cura total.',apply:()=>{state.maxHp+=30;state.hp=state.maxHp}},{icon:'⚔',name:'LÂMINA LONGA',desc:'Alcance +25% e golpe mais veloz.',apply:()=>{state.range*=1.25;state.attackSpeed=Math.max(.28,state.attackSpeed*.87)},{icon:'◈',name:'PELE DE FERRO',desc:'Receba 20% menos dano.',apply:()=>state.armor=Math.min(.65,state.armor+.2)}];const list=document.querySelector('#upgrade-list');list.innerHTML='';choices.sort(()=>Math.random()-.5).slice(0,3).forEach(c=>{const b=document.createElement('button');b.className='upgrade-option';b.innerHTML=`<span class="upgrade-icon">${c.icon}</span><span><b>${c.name}</b><small>${c.desc}</small></span><span class="pick">↗</span>`;b.onclick=()=>{c.apply();state.paused=false;document.querySelector('#upgrade-screen').classList.add('hidden');updateHud();showToast('BÊNÇÃO ADQUIRIDA')};list.append(b)});document.querySelector('#upgrade-screen').classList.remove('hidden')}
function attack(){if(!state.running||state.paused||state.attackTimer>0)return;state.attackTimer=state.attackSpeed;state.attackAnim=.28;const origin=hero.position;let targets=state.enemies.map(e=>({e,d:e.group.position.distanceTo(origin)})).filter(x=>x.d<state.range+1.1).sort((a,b)=>a.d-b.d);if(targets.length){const target=targets[0].e;const dir=target.group.position.clone().sub(origin);const forward=new THREE.Vector3(Math.sin(hero.rotation.y),0,Math.cos(hero.rotation.y));if(dir.normalize().dot(forward)<-.35&&targets.length>1)targets=targets.filter(t=>t.e!==target).concat(targets[0]);const hit=targets.slice(0,1+(state.level>24?1:0));for(const {e} of hit){e.hp-=state.damage;burst(e.group.position.clone().add(new THREE.Vector3(0,1,0)),0x8de4d0,5);floatLabel(`-${Math.floor(state.damage)}`,e.group.position);if(e.hp<=0)killEnemy(e);else{e.hpFront.scale.x=Math.max(.02,e.hp/e.maxHp);e.hpFront.position.x=-(1-e.hp/e.maxHp)*.34}}}else{burst(hero.position.clone().add(new THREE.Vector3(Math.sin(hero.rotation.y),1,Math.cos(hero.rotation.y)).multiplyScalar(1.6)),0xc7a158,4)}
 document.querySelector('#screen-flash').style.background='rgba(232,207,151,.1)';document.querySelector('#screen-flash').classList.remove('hit');void document.querySelector('#screen-flash').offsetWidth;document.querySelector('#screen-flash').classList.add('hit')}
function dash(){if(!state.running||state.paused||state.dashTimer>0)return;state.dashTimer=2.2;state.invuln=.55;let v=new THREE.Vector3(state.joy.x,0,state.joy.y);if(v.length()<.1){v.set(Math.sin(hero.rotation.y),0,Math.cos(hero.rotation.y))}v.normalize();hero.position.addScaledVector(v,2.4);hero.position.x=THREE.MathUtils.clamp(hero.position.x,-10.8,10.8);hero.position.z=THREE.MathUtils.clamp(hero.position.z,-10.8,10.8);burst(hero.position.clone().add(new THREE.Vector3(0,.5,0)),0x69e4d3,11);document.querySelector('#dash-btn').style.filter='brightness(.6)';setTimeout(()=>document.querySelector('#dash-btn').style.filter='',2200)}
function damageHero(amount){if(state.invuln>0)return;state.hp-=Math.max(1,amount*(1-state.armor));state.invuln=.55;document.querySelector('#screen-flash').style.background='rgba(238,81,62,.32)';document.querySelector('#screen-flash').classList.remove('hit');void document.querySelector('#screen-flash').offsetWidth;document.querySelector('#screen-flash').classList.add('hit');updateHud();if(state.hp<=0)endGame()}
function endGame(){state.running=false;document.querySelector('#end-title').textContent='A RUNA SE APAGA';document.querySelector('#end-copy').textContent=`Você chegou ao nível ${state.level} e derrotou ${state.kills} criaturas.`;document.querySelector('#end-screen').classList.remove('hidden')}
function winGame(){state.running=false;document.querySelector('#end-title').textContent='A ARENA É SUA';document.querySelector('#end-copy').textContent=`Nível 100 alcançado! Você derrotou ${state.kills} criaturas e dominou a runa.`;document.querySelector('#end-screen').classList.remove('hidden')}
function startGame(){document.querySelector('#start-screen').classList.add('hidden');document.querySelector('#end-screen').classList.add('hidden');state.running=true;state.paused=false;state.spawnTimer=.2;document.querySelector('#status-text').textContent='SOBREVIVA À ARENA';if(!state.enemies.length)for(let i=0;i<3;i++)makeEnemy()}
function restart(){for(const e of state.enemies)scene.remove(e.group);state.enemies=[];for(const e of state.effects)scene.remove(e.mesh);state.effects=[];state.level=1;state.xp=0;state.nextXp=24;state.hp=100;state.maxHp=100;state.damage=38;state.speed=5.1;state.attackSpeed=.55;state.range=2.6;state.armor=0;state.kills=0;state.time=0;hero.position.set(0,0,3.8);updateHud();startGame()}
document.querySelector('#play-btn').onclick=startGame;document.querySelector('#restart-btn').onclick=restart;document.querySelector('#attack-btn').addEventListener('pointerdown',e=>{e.preventDefault();attack()});document.querySelector('#dash-btn').addEventListener('pointerdown',e=>{e.preventDefault();dash()});
window.addEventListener('keydown',e=>{state.keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space')attack();if(e.code==='ShiftLeft'||e.code==='ShiftRight')dash()});window.addEventListener('keyup',e=>state.keys[e.code]=false);window.addEventListener('blur',()=>state.keys={});
const joystick=document.querySelector('#joystick'),knob=document.querySelector('#joy-knob');let joyPointer=null;
joystick.addEventListener('pointerdown',e=>{e.preventDefault();joyPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);moveJoy(e)});joystick.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)moveJoy(e)});function moveJoy(e){const r=joystick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=35,l=Math.hypot(dx,dy),k=Math.min(max,l),x=l?dx/l*k:0,y=l?dy/l*k:0;knob.style.transform=`translate(calc(-50% + ${x}px),calc(-50% + ${y}px))`;state.joy.x=x/max;state.joy.y=y/max}function resetJoy(){joyPointer=null;state.joy.x=state.joy.y=0;knob.style.transform='translate(-50%,-50%)'}joystick.addEventListener('pointerup',resetJoy);joystick.addEventListener('pointercancel',resetJoy);joystick.addEventListener('lostpointercapture',resetJoy);
let muted=false;document.querySelector('#sound-btn').onclick=()=>{muted=!muted;document.querySelector('#sound-btn').textContent=muted?'♪':'♫';showToast(muted?'SOM DESATIVADO':'SOM ATIVADO')};

